manual.pi:
float cos2(float f)
{
  return pow(cos(f), 2.0);
}

constant PI = 3.1415926535;

int main()
{
  write("The square of cos(pi/4) is " +
	.trig.cos2(.trig.PI/4) + ".\n");
  return 0;
}

import .trig; // Import the module from this directory

int main()
{
  write("The square of cos(pi/4) is " +
	cos2(PI/4) + ".\n");
  return 0;
}
